def _rel_from_path(co_filename):
    # Normalize both Windows ('\') and POSIX ('/') separators, then take the
    # last two components -> 'UserTools/x.py' | 'Commands/x.py'.
    p = co_filename.replace('\\', '/')
    parts = [x for x in p.split('/') if x]
    if len(parts) >= 2:
        return parts[-2] + '/' + parts[-1]
    return parts[-1] if parts else ''


def resolve_domain(co_filename, tool_name):
    '''Effective domain for a tool: 'core' if in CORE_TOOLS, else its file's domain.
    Unknown files fall back to 'misc' so a newly added file is never silently dropped.'''
    if tool_name in CORE_TOOLS:
        return 'core'
    rel = _rel_from_path(co_filename)
    return FILE_DOMAIN.get(rel, 'misc')
